def set_options(self, task_keys=None, var_options=None, direct=None):
    task_keys = dict(task_keys or {})
    # PlayContext still carries the CLI-only SSH arguments. Pass supplied
    # values through the option resolver so inventory variables can win.
    for option in ('ssh_common_args', 'sftp_extra_args', 'scp_extra_args', 'ssh_extra_args'):
        value = getattr(self._play_context, option, None)
        if value and not task_keys.get(option):
            task_keys[option] = value
    if self._play_context.private_key_file != C.DEFAULT_PRIVATE_KEY_FILE:
        task_keys.setdefault('private_key_file', self._play_context.private_key_file)
    if self._play_context.remote_user != C.DEFAULT_REMOTE_USER:
        task_keys.setdefault('remote_user', self._play_context.remote_user)
    # TaskExecutor supplies the core timeout even when no CLI or task
    # override was made. Let the SSH plugin's config value win then.
    if task_keys.get('timeout') == C.DEFAULT_TIMEOUT:
        task_keys.pop('timeout')
    super(Connection, self).set_options(task_keys=task_keys, var_options=var_options, direct=direct)

@staticmethod
def _create_control_path(host, port, user, connection=None, pid=None):
    '''Make a hash for the controlpath based on con attributes'''
    pstring = '%s-%s-%s' % (host, port, user)
    if connection:
        pstring += '-%s' % connection
    if pid:
        pstring += '-%s' % to_text(pid)
    m = hashlib.sha1()
    m.update(to_bytes(pstring))
    digest = m.hexdigest()
    cpath = '%(directory)s/' + digest[:10]
    return cpath

